def require(condition, message):
    if not condition:
        raise ValueError(message)


def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(',',':')).encode()


def same_typed(a,b):
    if type(a) is not type(b):return False
    if isinstance(a,dict):
        return a.keys()==b.keys() and all(same_typed(a[k],b[k])for k in a)
    if isinstance(a,list):
        return len(a)==len(b) and all(same_typed(x,y)for x,y in zip(a,b))
    return a==b


class Capture:
    def write_text(self,value):self.data=json.loads(value)


def input9550():
    directory=Path(__file__).resolve().parent.parent/'degree-five-triangular'
    for name,digest in INPUT_PINS.items():
        require(hashlib.sha256((directory/name).read_bytes()).hexdigest()==digest,
                'whole pinned9550 source '+name)
    spec=importlib.util.spec_from_file_location('odd_moment9550',directory/'verify.py')
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    capture=Capture();record=module.make_certificate(capture)
    require(same_typed(record,json.loads((directory/'expected.json').read_text())),
            'entire typed9550 input')
    require(hashlib.sha256(canonical(record)).hexdigest()==INPUT_RECORD,
            'entire9550 record')
    return module,capture.data


def certificate():
    k,data=input9550();P=k.P
    E,r,x,u=[k.variable(i)for i in (1,2,3,4)]
    checks={}
    def eq(label,left,right=0):
        require(P(left)==P(right),'whole polynomial identity '+label);checks[label]=True
    def decode(a):
        require(all(len(key)==5 and min(key[:4])>=0 and key[4]>=-1 for key,c in a),
                'entire9550 Laurent coefficient domain')
        return P({tuple(key+[0]*5):F(c)for key,c in a})
    def degree(a,index):return max((key[index]for key in a.c),default=-1)
    def primitive(a):
        require(bool(a.c),'nonzero primitive polynomial')
        den=lcm(*(c.denominator for c in a.c.values()));common=0
        for c in a.c.values():common=gcd(common,abs(int(c*den)))
        content=F(common,den);answer=(1/content)*a
        require(all(c.denominator==1 for c in answer.c.values()),'whole primitive integer coefficients')
        eq('whole positive-content reconstruction '+str(len(checks)),a,content*answer)
        return answer,content
    def transform(a,power):
        """B0, x=s^2,u=st, with stated KNOWN nonzero s multiplier."""
        out={}
        for key,c in a.c.items():
            if key[0]:continue
            exponent=key[3]-key[4]+power
            require(exponent>=0 and exponent%2==0,'entire q0 known-s parity')
            new=(0,key[1],key[2],exponent//2,key[4],0,0,0,0,0)
            out[new]=out.get(new,F(0))+c
        return P(out)
    def back(a,power):
        """Whole backward pullback; only the already known t inverse remains."""
        out={}
        for key,c in a.c.items():
            require(key[0]==0 and not any(key[5:]),'whole q0 polynomial slots')
            exponent=2*key[3]+key[4]+power
            require(exponent>=0,'whole backward known-s clearing')
            new=(0,key[1],key[2],exponent,key[4],0,0,0,0,0)
            out[new]=out.get(new,F(0))+c
        return P(out)
    old_h=[decode(a)for a in data['h_ascending']]
    old_R=[decode(a)for a in data['residuals_ascending']]
    old_F=old_h[2]
    Fs=transform(old_F,-1)
    eq('whole Fstar pullback including inverse-u term',back(Fs,1),k.extract(old_F,0,0))
    require(degree(Fs,1)==1,'entire Fstar is affine in E')
    eq('constant E pivot in Fstar_over_s',k.extract(Fs,1,1),F(-83,60))
    Es=F(60,83)*k.extract(Fs,1,0)
    eq('whole Fstar E recovery',k.sub(Fs,1,Es))
    original=[];primitive_rows=[];contents=[]
    for i,power in enumerate((2,1,2,1,2)):
        row=transform(old_R[i],power)
        eq('entire transformed residual pullback '+str(i),back(row,0),
           k.variable(3)**power*k.extract(old_R[i],0,0))
        original.append(row)
        specialized=k.sub(row,1,Es)
        require(all(key[0]==key[1]==0 and not any(key[5:]) and min(key[2:5])>=0
                    for key in specialized.c),'ALL five ordinary QQ[r,x,u] rows')
        require(degree(specialized,4)<=2,'ALL five rows quadratic in u')
        row,content=primitive(specialized)
        primitive_rows.append(row);contents.append(content)
    matrix=[[k.extract(row,4,j)for j in (2,1,0)]for row in primitive_rows]
    for i,row in enumerate(matrix):
        eq('complete five quadratic matrix row '+str(i),
           row[0]*u*u+row[1]*u+row[2],primitive_rows[i])
    triples=list(combinations(range(5),3));raw_minors=[];minors=[];mcontents=[]
    for triple in triples:
        determinant=P()
        for permutation in permutations(range(3)):
            inversions=sum(permutation[i]>permutation[j]for i in range(3)for j in range(i+1,3))
            term=P(-1 if inversions%2 else 1)
            for i,j in enumerate(permutation):term*=matrix[triple[i]][j]
            determinant+=term
        minor,content=primitive(determinant)
        require(content.denominator==1 and content>=1,'positive INTEGER determinant content')
        require(all(key[0]==key[1]==key[4]==0 and not any(key[5:])for key in minor.c),
                'entire bivariate determinant')
        raw_minors.append(determinant);minors.append(minor);mcontents.append(content)
    require(len(X_UNIT_MULTIPLIERS)==10,'all ten witness slots')
    multipliers=[]
    for encoded in X_UNIT_MULTIPLIERS:
        require(all(len(key)==2 and min(key)>=0 and sum(key)<=4 for key,c in encoded),
                'whole degree-four rational unit multiplier')
        require(len({tuple(key)for key,c in encoded})==len(encoded),'no duplicate witness monomial')
        multipliers.append(P({(0,0,key[0],key[1],0,0,0,0,0,0):F(c)for key,c in encoded}))
    eq('ENTIRE characteristic-zero primitive-minor x-unit',
       sum((a*b for a,b in zip(multipliers,minors)),P()),x)
    raw_multipliers=[(1/content)*a for a,content in zip(multipliers,mcontents)]
    eq('ENTIRE raw determinant x-unit',sum((a*b for a,b in zip(raw_multipliers,raw_minors)),P()),x)

    # Independent Newton coefficient bridge for the monic primitive of h.
    f=[P()]+[F(8,j+1)*a for j,a in enumerate(old_h)]
    moments={0:P(8)}
    for order in range(1,6):
        moments[order]=-sum((f[8-j]*moments[order-j]for j in range(1,order)),P())-order*f[8-order]
    eq('whole original cubic moment',moments[3],F(-24,5)*k.variable(0))
    eq('whole original fifth moment',moments[5],-4*k.variable(0)-F(40,3)*old_F)

    def norm1(a):return sum((abs(c)for c in a.c.values()),F(0))
    matrix_degree=max(sum(key[2:4])for row in matrix for a in row for key in a.c)
    multiplier_degree=max(sum(key[2:4])for a in multipliers for key in a.c)
    require(matrix_degree==5 and multiplier_degree==4,'whole norm degree budgets')
    Q=sum(norm1(a)**2 for row in matrix for a in row)
    cnorm=sum((norm1(a)for a in raw_multipliers),F(0))
    C=max(1,-(-cnorm.numerator//cnorm.denominator))
    require(Q.denominator==1 and cnorm<=C,'exact Frobenius and unit norms')

    def evaluate(a,rv,xv,uv=F(0),ev=F(0)):
        answer=F(0)
        for key,c in a.c.items():answer+=c*ev**key[1]*rv**key[2]*xv**key[3]*uv**key[4]
        return answer
    controls={}
    for rv in (F(-3,8),F(-3,7)):
        small=[[evaluate(a,rv,F(0))for a in row]for row in matrix]
        allzero=all(evaluate(a,rv,F(0)) == 0 for a in raw_minors)
        rank2=any(small[i][a]*small[j][b]-small[i][b]*small[j][a]!=0
                  for i,j in combinations(range(5),2)for a,b in combinations(range(3),2))
        controls['x0 rank TWO retained at r='+str(rv)]=allzero and rank2
    for uv in (F(-2),F(2)):
        rv,xv=F(-1,3),F(1)
        ev=evaluate(Es,rv,xv,uv)
        controls['signed-u F recovery and full residual exclusion u='+str(uv)]=(
           evaluate(Fs,rv,xv,uv,ev)==0 and
           any(evaluate(a,rv,xv,uv) != 0 for a in primitive_rows))
    controls['constant replacing x-unit is false']=sum((a*b for a,b in zip(multipliers,minors)),P())!=P(1)
    controls['inverse-u recovery excludes u0']=any(key[4] < 0 for key in Es.c)
    controls['x0 is not an original s0 chart']=allzero and x!=P(1)
    require(all(controls.values()),'all mathematical boundary controls')
    damages={}
    changed=list(multipliers);changed[0]=changed[0]+1
    damages['one entire rational unit coefficient changed']=sum((a*b for a,b in zip(changed,minors)),P())!=x
    changed=list(minors);changed[0]=changed[0]+r**9
    damages['highest determinant coefficient changed']=sum((a*b for a,b in zip(multipliers,changed)),P())!=x
    damages['remaining FIFTH row constant changed']=matrix[4][0]*u*u+matrix[4][1]*u+matrix[4][2]+1!=primitive_rows[4]
    damages['fifth moment critical coefficient omitted']=moments[5]!=-4*k.variable(0)
    damages['Fstar recovery sign changed']=k.sub(Fs,1,-Es)!=P()
    damages['u quadratic coefficient omitted']=matrix[0][1]*u+matrix[0][2]!=primitive_rows[0]
    require(all(damages.values()),'all meaningful mathematical damages')
    record={
        'actual_agent':'six-sendov-2','role':'researcher',
        'domain':'q=B/s=0; finite COMPLEX r,x,u with x*u!=0; Fstar=0; ALL FIVE full9550 residuals',
        'input9550':{'source_commit':INPUT_COMMIT,'pins':INPUT_PINS,'whole_record_sha256':INPUT_RECORD,
                     'whole_typed_parent_regenerated':True},
        'same_author_arithmetic_reused':'9550 exact sparse Laurent arithmetic; not an independent implementation',
        'whole_Fstar_over_s_q0':Fs.encoded(),'constant_E_pivot':'-83/60',
        'whole_E_recovery':Es.encoded(),'whole_transformed_original_residuals':[a.encoded()for a in original],
        'whole_specialized_positive_contents':[str(c)for c in contents],
        'whole_Fstar_zero_primitive_quadratics':[a.encoded()for a in primitive_rows],
        'matrix_monomial_order':['u^2','u','1'],
        'whole_five_by_three_matrix':[[a.encoded()for a in row]for row in matrix],
        'minor_row_triples':[list(t)for t in triples],
        'whole_primitive_three_by_three_minors':[a.encoded()for a in minors],
        'whole_positive_integer_determinant_contents':[str(c)for c in mcontents],
        'whole_primitive_minor_x_unit_multipliers':X_UNIT_MULTIPLIERS,
        'whole_unit_target':x.encoded(),
        'whole_original_moment3':moments[3].encoded(),'whole_original_moment5':moments[5].encoded(),
        'whole_polynomial_identities':checks,'mathematical_boundary_controls':controls,
        'rejected_mathematical_damages':damages,
        'exact_matrix_Frobenius_coefficient_bound_Q':str(Q),
        'exact_raw_unit_coefficient_norm':str(cnorm),'integer_unit_coefficient_bound_C':C,
        'matrix_entry_degree':matrix_degree,'unit_multiplier_degree':multiplier_degree,
        'complex_residual_bound':'M>=1, |r|,|x|<=M: ||P(r,x,u)||_2 >= 2*|x|*sqrt(1+|u|^2+|u|^4)/(C*Q*M^14); x!=0',
        'original_claim':'At every balanced norm-one eight-DISTINCT-real-original angular stationary profile, original cubic and fifth moments cannot both vanish.',
        'ordinary_bridges':'9550 complete feasible chart and B=s=0 exclusion; legal known-s/t transformation; constant E pivot; common finite u implies all3x3 determinants zero without rank divisions; entire QQ polynomial x-unit; Newton identities; Cauchy-Binet and singular values; fixed-separation compactness. Unformalized.',
        'discovery_prime_is_a_mathematical_premise':False,
        'CAS_or_Groebner_status_is_a_mathematical_premise':False,
        'x0_rank_three_claimed':False,'u0_original_chart_claimed':False,
        'original_collisions_included':False,'uniform_collision_limit_claimed':False,
        'positive_separated_stationary_set_claimed_nonempty':False,
        'stationary_profiles_classified':False,'complex_first_power_proved':False,
        'independently_reviewed':False}
    return record


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--expected',type=Path,default=Path(__file__).with_name('expected.json'))
    parser.add_argument('--write-expected',action='store_true')
    args=parser.parse_args();record=certificate()
    if args.write_expected:args.expected.write_bytes(canonical(record)+b'\n')
    else:require(same_typed(record,json.loads(args.expected.read_text())),'ENTIRE typed expected certificate')
    print(json.dumps({'whole_record_sha256':hashlib.sha256(canonical(record)).hexdigest(),
       'whole_polynomial_identities':len(record['whole_polynomial_identities']),
       'all_quadratic_rows':5,'all_fixed_three_by_three_minors':10,
       'entire_rational_unit_coefficients':sum(len(a)for a in X_UNIT_MULTIPLIERS),
       'matrix_entry_degree':record['matrix_entry_degree'],'unit_multiplier_degree':record['unit_multiplier_degree'],
       'unit_coefficient_bound_C':record['integer_unit_coefficient_bound_C'],
       'matrix_coefficient_bound_Q':record['exact_matrix_Frobenius_coefficient_bound_Q'],
       'mathematical_boundary_controls':len(record['mathematical_boundary_controls']),
       'rejected_mathematical_damages':len(record['rejected_mathematical_damages']),
       'original_cubic_and_fifth_moments_joint_zero_excluded':True,
       'complex_first_power_proved':False,'independently_reviewed':False},sort_keys=True))


if __name__=='__main__':main()
